"""Private test harness: synthetic fixture DNS, loopback-only real sockets."""
import ipaddress
import socket
import sys

import pytest


def deny_network(event, args):
    if event not in {'socket.connect', 'socket.getaddrinfo'}:
        return
    address = args[1] if event == 'socket.connect' else args[0]
    host = address[0] if isinstance(address, tuple) else address
    if host == 'localhost':
        return
    try:
        address = ipaddress.ip_address(host)
    except ValueError:
        pass
    else:
        if event == 'socket.getaddrinfo' or address.is_loopback:
            return
    raise RuntimeError('Optional SDK qualification prohibits external network access')


sys.addaudithook(deny_network)


@pytest.fixture(autouse=True)
